import { columns } from "@/components/Column";
import { DataTable } from "@/components/Table";
import { ScrollArea } from "@/components/ui/scroll-area";
import React, { useEffect } from "react";
import {
  Table,
  TableBody,
  TableCaption,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { getAppointmentbyPatient } from "@/lib/store/AsyncThunks";
import { useDispatch, useSelector } from "react-redux";
import { getpatientID } from "@/lib/store/UserSlice";

import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Button } from "@/components/ui/button";
import { Loader } from "lucide-react";
import { Link } from "react-router-dom";
import { useToast } from "@/components/ui/use-toast";

const UserAppoint = () => {
  const [appointments, setAppointments] = React.useState(null);
  const [noappointment , setNoAppointment] = React.useState(false)
  const {toast} = useToast()
  
  const dispatch = useDispatch();
  const patientID = useSelector(getpatientID);
  const href=`/patient/${patientID}/appointment`
  useEffect(() => {
    const getAppointments = async () => {
      try{
      const response = await dispatch(
        getAppointmentbyPatient({ patientID })
      ).unwrap();
      setNoAppointment(false)
      setAppointments(response);
      console.log(response);
    }catch(err){
      setNoAppointment(true)
      toast("Login Again")
      console.log(err)
    }
    };

    getAppointments();
  }, []);

  const sortedAppointments = appointments?.sort(

    (a, b) => {new Date(a?.date) - new Date(b?.date)}
  );

  // Get the current date and time
  const now = new Date();

  // Find last appointment (the latest one before now)
  const lastAppointment = sortedAppointments
    ?.filter((appt) => new Date(appt?.date) < now)
    .pop();
  const lastAppointmentDate = new Date(lastAppointment?.date);
  // Find upcoming appointment (the earliest one after now)
  const upcomingAppointment = sortedAppointments?.find(
    (appt) => new Date(appt?.date) > now
  );
  const upcomingAppointmentDate = new Date(
    upcomingAppointment?.date
  );
  return (
    <div className="w-full h-full pt-7 container remove-scrollbar">
      <h1 className=" text-3xl font-bold ">Appointments</h1>
      <Button className="mt-5 bg-green-500"  > <Link to={href}>Schedule Appointment</Link></Button>
{ lastAppointment ? appointments ? <>
      <div className=" flex flex-col md:flex-row items-center  ">
        <div className="pt-6 grow">
          Last Appointment
          <div className="stat-card  bg-pending w-fit mt-4  ">
            <h2 className="text-2xl font-semibold text-white">
              Dr. {lastAppointment?.doctorID.name|| "No Appointments"}
            </h2>
            <div className=" flex flex-col gap-2 text-[1rem] ">
              <p>Reason : {lastAppointment?.reason || "  "}</p>
              <p className=""> Date : {lastAppointmentDate.toDateString()}</p>
              <p>
                Prescription :{" "}
                {lastAppointment?.appointment?.prescription || "  "}
              </p>
              <p>Notes : {lastAppointment?.notes || "  "}</p>
            </div>
          </div>
        </div>
        <div className="pt-6 grow">
          Upcoming Appointment
          <div className="stat-card  bg-pending w-fit mt-4  ">
            <h2 className="text-2xl font-semibold text-white">
              Dr. {upcomingAppointment?.doctorID.name || "No Appointments"}
            </h2>
            <div className=" flex flex-col gap-2 text-[1rem] ">
              <p>{upcomingAppointment?.reason ? `Reason : ${upcomingAppointment?.reason}`   : " " || "  "}</p>
              <p className="">
                {" "}
                Date : {upcomingAppointmentDate.toDateString()}
              </p>
              <p>
                
              </p>
            </div>
          </div>
        </div>
        <div className="">
          <h1 className=" p-6"> Previous Appointments</h1>

          {appointments ? (
            <>
              <ScrollArea className=" h-[19rem] bg-pending  bg-blend-soft-light  rounded-xl p-4">
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead className="w-[100px]">Doctor</TableHead>
                      <TableHead>Date</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {appointments?.map((appointment) => {
                      console.log(appointment)
                      const date = new Date(appointment?.date);
                      return (
                        <Dialog key={appointment._id}>
                          <DialogTrigger asChild>
                            <TableRow
                              key={appointment._id}
                              className="hover:cursor-pointer"
                            >
                              <TableCell className="font-medium text-nowrap">
                                {appointment?.doctorID.name}
                              </TableCell>
                              <TableCell>{date.toDateString()}</TableCell>
                            </TableRow>
                          </DialogTrigger>
                          <DialogContent className="sm:max-w-[425px] text-white jakarta border-0 bg-black rounded-full">
                            <DialogHeader>
                              <DialogTitle className="text-center text-2xl">
                                Appointment details
                              </DialogTitle>
                            </DialogHeader>
                            <div className="grid gap-4 py-4">
                              <div className="grid grid-cols-4 items-center gap-4">
                                <Label htmlFor="name" className="text-right">
                                  Doctor
                                </Label>
                                <Input
                                  id="name"
                                  value={appointment?.doctorID.name}
                                  className="col-span-3 shad-input"
                                />
                              </div>
                              <div className="grid grid-cols-4 items-center gap-4">
                                <Label
                                  htmlFor="username"
                                  className="text-right"
                                >
                                  Date
                                </Label>
                                <Input
                                  id="username"
                                  value={date.toDateString()}
                                  className="col-span-3 shad-input"
                                />
                              </div>
                              <div className="grid grid-cols-4 items-center gap-4">
                                <Label
                                  htmlFor="username"
                                  className="text-right"
                                >
                                  Type
                                </Label>
                                <Input
                                  id="username"
                                  value={appointment.status}
                                  className="col-span-3 shad-input"
                                />
                              </div>
                              <div className="grid grid-cols-4 items-center gap-4">
            <strong className="text-center">Prescription:</strong>
            
            {appointment.prescription.length >0 ? <ScrollArea className="mt-2 col-span-5  bg-[#1a1d21] rounded-lg  max-h-40">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableCell>Medicine Name</TableCell>
                    <TableCell>Dosage</TableCell>
                    <TableCell>Frequency</TableCell>
                    <TableCell>Duration</TableCell>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {appointment.prescription.map((item, index) => (
                    <TableRow key={index}>
                      <TableCell>{item.name}</TableCell>
                      <TableCell>{item.dosage}</TableCell>
                      <TableCell>{item.frequency}</TableCell>
                      <TableCell>{item.duration}</TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </ScrollArea> : <Input
                                  id="username"
                                  value={
                                    
                                    " No  Notes"
                                  }
                                  className="col-span-3 shad-input"
                                  
                                />}

          </div>
                              <div className="grid grid-cols-4 items-center gap-4">
                                <Label
                                  htmlFor="username"
                                  className="text-right"
                                >
                                  Notes
                                </Label>
                                <Input
                                  id="username"
                                  value={
                                    appointment.notes ||
                                    " No  Notes"
                                  }
                                  className="col-span-3 shad-input"
                                  
                                />
                              </div>
                            </div>
                          </DialogContent>
                        </Dialog>
                      );
                    })}
                  </TableBody>
                </Table>
              </ScrollArea>
            </>
          ) : (
            <ScrollArea className=" h-[15rem] bg-pending  bg-blend-soft-light  rounded-xl p-4 text-xl font-bold text-center ">
              No Appointments
            </ScrollArea>
          )}
        </div>
      </div>

</> : <>
<div className=" h-full w-full relative">
            <Loader className="animate-spin h-10 w-10 absolute top-1/3 right-1/2" />
          </div>

</> :<p className="pt-5">No Appointments found</p> }

      {/* <DataTable columns={columns}  /> */}
    </div>
  );
};

export default UserAppoint;